 }

def dedupe_preserve_order(lst): 
     seen = set() 
     seen_unhashable = [] 
     result = [] 
     for item in lst: 
         try: 
             if item not in seen: 
                 seen.add(item) 
                 result.append(item) 
         except TypeError: 
             if item not in seen_unhashable: 
                 seen_unhashable.append(item) 
                 result.append(item) 
     return result
